           'LD_LIBRARY_PATH':str(pathlib.Path(SITE).parent/'native')}
    entry = str(pathlib.Path(submission)/'run.py')
    def limits():
        for kind, values in [(resource.RLIMIT_AS, (1024*1024**2,)*2),
                             (resource.RLIMIT_CPU, (120, 121)),
                             (resource.RLIMIT_NOFILE, (32, 32)),
                             (resource.RLIMIT_NPROC, (64, 64)),
                             (resource.RLIMIT_FSIZE, (64*1024**2,)*2),
                             (resource.RLIMIT_CORE, (0, 0))]:
            resource.setrlimit(kind, values)
    start = time.monotonic()
    p = subprocess.run([sys.executable, '-I', '-B', entry], input=data,
                       capture_output=True, env=env, cwd=scratch, preexec_fn=limits,
                       timeout=timeout)
    return p.returncode, p.stdout, p.stderr, time.monotonic()-start

def strict_json(data):
    def bad(_):
        raise ValueError('nonfinite JSON')
    def unique(pairs):
        d = {}
        for k, v in pairs:
            if k in d: raise ValueError('duplicate')
            d[k] = v
        return d
    return json.loads(data.decode('utf-8'), object_pairs_hook=unique, parse_constant=bad, parse_float=bad)

def main():
    sub = sys.argv[1] if len(sys.argv)>1 else '/workspace/submission'
    fixtures = json.loads(pathlib.Path('/workspace/examples.json').read_text())
    ok = True
    for case in fixtures:
        data = (case['raw'].encode() if 'raw' in case else json.dumps(case['request'], separators=(',',':')).encode())
        rc, out, err, secs = run_case(sub, data)
        if rc:
            print(case['name'], 'NONZERO', rc, err.decode()[:2000]); ok=False; continue
        try:
            answer = strict_json(out)
        except Exception as exc:
            print(case['name'], 'BADJSON', exc, out[:200]); ok=False; continue
        same = json.dumps(answer,sort_keys=True)==json.dumps(case['response'],sort_keys=True)
        print(f"{case['name']}: {'MATCH' if same else 'MISMATCH'} ({secs:.2f}s, {len(out)} bytes)")
        if not same:
            ok=False
            print(' got:', json.dumps(answer)[:1500])
            print(' exp:', json.dumps(case['response'])[:1500])
    print('ALL OK' if ok else 'FAILURES')

if __name__ == '__main__':
    main()
