"""Independent slow reference implementation of PROTOCOL.md for cross-checking."""
import itertools, json
from decimal import Decimal, getcontext
from fractions import Fraction
getcontext().prec = 80

PAD = 1514

def real_len(values):
    for i, v in enumerate(values):
        if v == PAD: return i
    return len(values)

def ref_fragments(rows, width):
    frags = []
    for ri, row in enumerate(rows):
        values, act = row['values'], row['activation']
        n = real_len(values)
        if n == 0: continue
        a = act[:n]
        mean = Decimal(sum(a))/Decimal(n)
        std = (sum((Decimal(x)-mean)**2 for x in a)/Decimal(n)).sqrt()
        thr = mean + std
        high = [x > thr for x in a]
        j = 0
        while j < n:
            if not high[j]: j += 1; continue
            s = j
            while j < n and high[j]: j += 1
            L = j - s
            if L < 2: continue
            if L <= width:
                frags.append((ri, s, L, row['class'], tuple(values[s:s+L])))
            else:
                best = None
                for p in range(s, s+L-width+1):
                    t = sum(a[p:p+width])
                    if best is None or t > best[0]: best = (t, p)
                frags.append((ri, best[1], width, row['class'], tuple(values[best[1]:best[1]+width])))
    return frags

def ref_interval(seqs):
    n = len(seqs); L = len(seqs[0]); out = []
    for i in range(L):
        col = [s[i] for s in seqs]
        lo, hi = min(col), max(col)
        mean = Decimal(sum(col))/Decimal(n)
        sigma = (sum((Decimal(v)-mean)**2 for v in col)/Decimal(n)).sqrt()
        d1 = Decimal(lo)-sigma; d2 = Decimal(hi)+sigma
        lo_t = int(d1.to_integral_value(rounding='ROUND_DOWN')) if d1 >= 0 else int(d1.to_integral_value(rounding='ROUND_UP'))
        out.append((max(0, lo_t), min(3028, int(d2.to_integral_value(rounding='ROUND_DOWN')))))
    return out

def ref_dist_leq(a, b, p, q):
    L = len(a); S = 0; A = 0
    for x, y in zip(a, b):
        d = abs(x-y)
        if (x < 1514 < y) or (y < 1514 < x): d += 1000
        S += d*d
        if x == y: A += 1
    return S*(9**A)*q*q <= L*(25**A)*p*p

def ref_clusters(frags, eps, ratio):
    p, q = eps; rp, rq = ratio
    groups = {}; counts = {}
    for fid, f in enumerate(frags):
        groups.setdefault((f[3], len(f[4])), []).append(fid)
        counts[f[3]] = counts.get(f[3], 0)+1
    clusters = []
    for (cls, L), fids in groups.items():
        m = counts[cls]
        dmin = max(2, -((-m*rp)//rq))
        n = len(fids)
        adj = [[i == j or ref_dist_leq(frags[fids[i]][4], frags[fids[j]][4], p, q)
                for j in range(n)] for i in range(n)]
        cores = [i for i in range(n) if sum(adj[i]) >= dmin]
        comp = {}; lab = 0; seen = set()
        for c in cores:
            if c in seen: continue
            stack = [c]; seen.add(c); grp = []
            while stack:
                cur = stack.pop(); grp.append(cur)
                for o in cores:
                    if o not in seen and adj[cur][o]: seen.add(o); stack.append(o)
            for g in grp: comp[g] = lab
            lab += 1
        cmin = {}
        for c, l in comp.items(): cmin[l] = min(cmin.get(l, 10**9), fids[c])
        l2i = {v: k for k, v in cmin.items()}
        here = {l: ([fids[c] for c in cores if comp[c] == l], cmin[l]) for l in cmin}
        for i in range(n):
            if i in cores: continue
            labs = {comp[j] for j in cores if adj[i][j]}
            if labs:
                here[l2i[min(cmin[l] for l in labs)]][0].append(fids[i])
        for l, (members, cid) in here.items():
            clusters.append({'id': cid, 'class': cls,
                             'members': sorted(members),
                             'core': sorted(fids[c] for c in cores if comp[c] == l),
                             'range': ref_interval([frags[f][4] for f in sorted(members)])})
    clusters.sort(key=lambda c: c['id'])
    noise = sorted(set(range(len(frags))) - {f for c in clusters for f in c['members']})
    return clusters, noise

def ref_match_window(prefix, pattern):
    L = len(pattern)
    for s in range(0, len(prefix)-L+1):
        if all(lo <= prefix[s+i] <= hi for i, (lo, hi) in enumerate(pattern)):
            return True
    return False

def ref_exact_entries(patterns, limit):
    keys = set()
    for pat in patterns:
        coords = [[v for v in range(lo, hi+1) if v != PAD] for lo, hi in pat]
        if any(not c for c in coords): continue
        for combo in itertools.product(*coords):
            keys.add((len(pat), combo))
    return min(len(keys), limit)

def ref_release(spec, capacity):
    width = spec['width']; classes = spec['classes']
    frags = ref_fragments(spec['discovery'], width)
    clusters, noise = ref_clusters(frags, spec['eps'], spec['ratio'])
    prefixes = [row['values'][:real_len(row['values'])] for row in spec['validation']]
    counts = [0]*classes
