        t = c['class']
        cin = Fraction(hits[t], counts[t]) if counts[t] else Fraction(0)
        others = [Fraction(hits[x], counts[x]) for x in range(classes) if x != t and counts[x]]
        cout = max(others) if others else Fraction(0)
        c['hits'] = hits
        c['score'] = cin/(cout + Fraction(1, 10000))
        c['kept'] = c['score'] > Fraction(spec['threshold'][0], spec['threshold'][1])
    kept = sorted([c for c in clusters if c['kept']], key=lambda c: (-c['score'], c['id']))
    if spec['mode'] == 'range':
        entries = len(kept)
    else:
        entries = ref_exact_entries([c['range'] for c in kept], capacity['exact']+1)
    # backup: same pinned sklearn path
    sys_path = None
    import numpy as np
    from sklearn.tree import DecisionTreeClassifier
    X = np.array([[r['values'][:width] + [PAD]*(width-len(r['values'][:width]))] [0] for r in spec['train']], dtype=np.int32)
    y = np.array([r['class'] for r in spec['train']])
    model = DecisionTreeClassifier(max_depth=10, random_state=42, class_weight='balanced')
    model.fit(X, y)
    tr = model.tree_; classes_ = [int(v) for v in model.classes_]
    nodes = []
    for i in range(tr.node_count):
        if tr.children_left[i] == -1:
            nodes.append([classes_[int(np.argmax(tr.value[i][0]))]])
        else:
            nodes.append([int(tr.feature[i]), int(round(2*float(tr.threshold[i]))),
                          int(tr.children_left[i]), int(tr.children_right[i])])
    def predict(feats):
        node = nodes[0]
        while len(node) == 4:
            f, thr, l, r = node
            node = nodes[l if 2*feats[f] <= thr else r]
        return node[0]
    item = {'id': spec['id'],
            'fragments': [[f[0], f[1], f[2]] for f in frags],
            'noise': noise,
            'clusters': [{'id': c['id'], 'class': c['class'], 'members': c['members'],
                          'core': c['core'],
                          'range': [[lo, hi] for lo, hi in c['range']],
                          'hits': c['hits'],
                          'score': [c['score'].numerator, c['score'].denominator],
                          'kept': c['kept']} for c in clusters],
            'priority': [c['id'] for c in kept],
            'backup': nodes, 'entries': entries}
    return item, {'id': spec['id'], 'mode': spec['mode'], 'entries': entries,
                  'width': width, 'packet_limit': spec['packet_limit'],
                  'idle_us': spec['idle_us'], 'predict': predict,
                  'patterns': [(c['id'], c['class'], len(c['range']), c['range']) for c in kept]}

def ref_execute(request):
    from online_matching.train_rf import backup_predict  # not used; local predict
    capacity = request['capacity']
    catalog = []; models = {}
    for spec in request['releases']:
        item, model = ref_release(spec, capacity)
        catalog.append(item); models[spec['id']] = model
    current = None; residents = {}; pins = {}; active = {}; opened = {}
    installs = []; decisions = []
    def used():
        return {'range': sum(v for k, v in residents.items() if models[k]['mode'] == 'range'),
                'exact': sum(v for k, v in residents.items() if models[k]['mode'] == 'exact')}
    at = 0
    for block in request['blocks']:
        for ev in block:
            op = ev[0]
            if op == 'install':
                rid = ev[1]; m = models[rid]
                if m['entries'] > capacity[m['mode']]: status = 'oversize'
                else:
                    pros = dict(residents)
                    if current is not None and current != rid and pins.get(current, 0) == 0:
                        del pros[current]
                    pros[rid] = m['entries']
                    ru = sum(v for k, v in pros.items() if models[k]['mode'] == 'range')
                    eu = sum(v for k, v in pros.items() if models[k]['mode'] == 'exact')
                    if ru > capacity['range'] or eu > capacity['exact']: status = 'busy'
                    else:
                        status = 'ok'; residents = pros; current = rid
                installs.append({'at': at, 'id': rid, 'status': status,
                                 'resident': sorted(residents), 'used': used()})
            elif op == 'open':
                fid = ev[1]
                if fid in active or current is None: return {'error': 'invalid_request'}
                ep = {'flow': fid, 'epoch': opened.get(fid, 0), 'release': current,
                      'm': models[current], 'feats': [], 'consumed': 0, 'dir': None,
                      'last': None, 'committed': False}
                opened[fid] = ep['epoch']+1
                active[fid] = ep
                pins[current] = pins.get(current, 0)+1
            elif op == 'packet':
                fid, ts, src, length = ev[1], ev[2], ev[3], ev[4]
                ep = active.get(fid)
                if ep is None: return {'error': 'invalid_request'}
                if ep['last'] is not None and ts < ep['last']: return {'error': 'invalid_request'}
                m = ep['m']
                if ep['dir'] is None: ep['dir'] = src
                enc = 1514+length if src == ep['dir'] else 1514-length
                gap = None if ep['last'] is None else ts-ep['last']
                ep['last'] = ts
                if ep['committed']: at += 1; continue
                if ep['consumed'] >= m['width'] and gap is not None and gap > m['idle_us']:
                    w = m['width']
                    feats = ep['feats'][:w] + [PAD]*(w-len(ep['feats'][:w]))
                    decisions.append({'flow': fid, 'epoch': ep['epoch'], 'release': ep['release'],
                                      'at': at, 'seen': ep['consumed'], 'class': m['predict'](feats),
                                      'reason': 'idle', 'rule': None, 'start': None})
                    ep['committed'] = True; at += 1; continue
                ep['feats'].append(enc); ep['consumed'] += 1
                best = None
                for (cid, cls, L, pattern) in m['patterns']:
                    if ep['consumed'] >= L and ref_match_window(ep['feats'][ep['consumed']-L:], pattern):
                        best = (cid, cls, L); break
                if best is not None:
                    decisions.append({'flow': fid, 'epoch': ep['epoch'], 'release': ep['release'],
                                      'at': at, 'seen': ep['consumed'], 'class': best[1],
                                      'reason': 'segment', 'rule': best[0],
                                      'start': ep['consumed']-best[2]})
                    ep['committed'] = True; at += 1; continue
                if ep['consumed'] > m['packet_limit']:
                    w = m['width']
                    feats = ep['feats'][:w] + [PAD]*(w-len(ep['feats'][:w]))
                    decisions.append({'flow': fid, 'epoch': ep['epoch'], 'release': ep['release'],
                                      'at': at, 'seen': ep['consumed'], 'class': m['predict'](feats),
                                      'reason': 'limit', 'rule': None, 'start': None})
                    ep['committed'] = True; at += 1; continue
            else:
                fid = ev[1]; ep = active.pop(fid, None)
                if ep is None: return {'error': 'invalid_request'}
                if not ep['committed']:
                    w = ep['m']['width']
                    feats = ep['feats'][:w] + [PAD]*(w-len(ep['feats'][:w]))
                    decisions.append({'flow': fid, 'epoch': ep['epoch'], 'release': ep['release'],
                                      'at': at, 'seen': ep['consumed'], 'class': ep['m']['predict'](feats),
                                      'reason': 'close', 'rule': None, 'start': None})
                r = ep['release']
                left = pins.get(r, 0)-1
                if left > 0: pins[r] = left
                else:
                    pins.pop(r, None)
                    if current != r: residents.pop(r, None)
            at += 1
    if active: return {'error': 'invalid_request'}
    return {'catalog': catalog, 'installs': installs, 'decisions': decisions,
            'final': {'current': current, 'resident': sorted(residents), 'used': used()}}
