"""Coverage calibration, score filtering and exact release-bank sizing."""
import heapq

from fractions import Fraction

import numpy as np

PADDING = 1514


class _Exceeded(Exception):
    """Internal signal: the distinct exact-key count provably reached the cap."""


def _count_union(boxes, limit):
    """Exact ``min(|union of boxes|, limit)`` for one pattern length.

    ``boxes`` holds per-coordinate tuples of inclusive integer sub-intervals
    with the padding value already removed. Each coordinate is decomposed into
    the elementary intervals induced by the active boxes, so membership is
    constant on every branch and the union is counted exactly. Every subtree
    total lower-bounds the whole union, so the walk aborts as soon as the cap
    is provably reached.
    """
    if not boxes:
        return 0
    length = len(boxes[0])
    suffix = []
    for box in boxes:
        sizes = [0]*(length+1)
        running = 1
        for coordinate in range(length-1, -1, -1):
            running *= sum(end-start+1 for start, end in box[coordinate])
            sizes[coordinate] = running
        suffix.append(sizes)
    memo = {}

    def walk(depth, active):
        if depth == length:
            return 1
        if not active:
            return 0
        widest = 0
        for box in active:
            if suffix[box][depth] > widest:
                widest = suffix[box][depth]
        if widest >= limit:
            raise _Exceeded()
        key = (depth, active)
        found = memo.get(key)
        if found is not None:
            return found
        intervals = sorted((start, end, box) for box in active
                           for start, end in boxes[box][depth])
        points = sorted({point for interval in intervals
                         for point in (interval[0], interval[1]+1)})
        covering = []
        cursor = 0
        total = 0
        for index in range(len(points)-1):
            low = points[index]
            high = points[index+1]-1
            while cursor < len(intervals) and intervals[cursor][0] <= low:
                start, end, box = intervals[cursor]
                cursor += 1
                if end >= low:
                    heapq.heappush(covering, (end, box))
            while covering and covering[0][0] < high:
                heapq.heappop(covering)
            values = (high-low+1) - (1 if low <= PADDING <= high else 0)
            if values <= 0 or not covering:
                continue
            sub = tuple(sorted({box for _end, box in covering}))
            total += values*walk(depth+1, sub)
            if total >= limit:
                raise _Exceeded()
        memo[key] = total
        return total

    try:
        return walk(0, tuple(range(len(boxes))))
    except _Exceeded:
        return limit


def exact_bank_entries(patterns, limit):
    """``min(distinct exact keys, limit)`` over every kept pattern."""
    if limit <= 0:
        return 0
    groups = {}
    for pattern in patterns:
        coordinates = []
        empty = False
        for low, high in pattern:
            parts = []
            if low <= PADDING-1:
                parts.append((low, min(high, PADDING-1)))
            if high >= PADDING+1:
                parts.append((max(low, PADDING+1), high))
            if not parts:
                empty = True
                break
            coordinates.append(tuple(parts))
        if empty:
            continue
        groups.setdefault(len(coordinates), set()).add(tuple(coordinates))
    total = 0
    for _length in sorted(groups):
        total += _count_union(sorted(groups[_length]), limit-total)
        if total >= limit:
            return limit
    return total


def matching_rows(automaton, rows):
    """Boolean table ``table[pattern][row]`` of validation-row coverage."""
    table = np.zeros((len(automaton.ids), len(rows)), dtype=bool)
    for index, values in enumerate(rows):
        if not values:
            continue
        ranks = automaton.match_anywhere(values)
        if len(ranks):
            table[np.asarray(ranks, dtype=np.int64), index] = True
    return table


def real_prefix(values):
    for index, value in enumerate(values):
        if value == PADDING:
            return index
    return len(values)


def calibrate(clusters, validation_rows, threshold, classes, automaton):
    """Attach exact ``hits``, exact ``score`` and ``kept`` to every cluster."""
    counts = np.zeros(max(1, classes), dtype=np.int64)
    for row in validation_rows:
        counts[row['class']] += 1
    table = None
    if automaton.ids:
        prefixes = [row['values'][:real_prefix(row['values'])] for row in validation_rows]
        table = matching_rows(automaton, prefixes)
    keep_below = Fraction(threshold[0], threshold[1])
    for cluster in clusters:
        hits = [0]*classes
        if table is not None:
            for index in np.nonzero(table[cluster['index']])[0]:
                hits[validation_rows[int(index)]['class']] += 1
        target = cluster['class']
        denominator = int(counts[target])
        inner = Fraction(hits[target], denominator) if denominator else Fraction(0)
        outer = 0
        for other in range(classes):
            if other == target or not int(counts[other]):
                continue
            candidate = Fraction(hits[other], int(counts[other]))
            if candidate > outer:
                outer = candidate
        score = inner/(outer + Fraction(1, 10000))
        cluster['hits'] = hits
        cluster['score'] = score
        cluster['kept'] = bool(score > keep_below)
    return clusters
